//! WebAssembly facade over `manifest-core` for the Node runtime
//! (`@manifest/runtime`).
//!
//! Each export copies its JS arguments through [`bridge`], calls core or parser,
//! and returns plain JS objects or opaque [`handles`]. Every parameter and return
//! value is annotated with a TypeScript type generated by specta, so
//! `manifest_wasm.d.ts` names the same types as `@manifest/metadata` and
//! `@manifest/runtime` and never falls back to `any`.
//!
//! Errors are thrown as plain `{ code, path, message, fields }` objects; see
//! [`error`]. The Node facade turns them into `ManifestRuntimeError`.

use wasm_bindgen::prelude::*;

mod bridge;
mod error;
mod handles;
mod manifest;
mod parse;
mod plan;
mod verify;
mod wire;

pub use handles::{DownloadPlan, SelectedArtifact, ValidatedManifest, VersionPlan};
pub use manifest::{
    artifact_checksum_kind, list_variant_checksum_kinds, select_variant, validate_manifest,
};
pub use parse::{finish_checksum, finish_version, parse_checksum, parse_version};
pub use plan::{plan_download, plan_version, render_artifact, render_template};
pub use verify::{check_policy, compare_digest};
pub use wire::{LimitsInput, RemoteResponseInput, RenderedArtifact, TemplateValue};

/// Type imports for the annotations on the exports. The plan value types are
/// aliased because the handle classes reuse their names.
#[wasm_bindgen(typescript_custom_section)]
const TYPE_IMPORTS: &str = r#"
import type {
  ChecksumAlgorithm,
  RemoteChecksumParser,
  RemoteVersionParser,
  ResourceArtifactTemplate,
  ResourceChecksum,
  ResourceManifest,
  ResourceVariant,
  SupportedPlatform,
} from "@manifest/metadata";
import type {
  ChecksumKind,
  DownloadOptions,
  DownloadPlan as DownloadPlanValue,
  LimitsInput,
  RemoteResponseInput,
  RenderedArtifact,
  ResolvedChecksum,
  TemplateValue,
  VariantChecksumKind,
  VariantSelection,
  VerifyPolicy,
  VersionOptions,
  VersionPlan as VersionPlanValue,
} from "../src/types.ts";
"#;
